"""Plot evidence generated by the completed experiment."""
import matplotlib
matplotlib.use("Agg")  # File-only backend: works in VS Code terminals and headless environments.
import matplotlib.pyplot as plt
import pandas as pd


def save_plots(losses, test_prob, test_unc, test_y, comparison, plot_dir):
    plt.style.use("seaborn-v0_8-whitegrid")
    fig, ax = plt.subplots(figsize=(7, 4)); ax.plot(losses, color="#386cb0"); ax.set(title="Training loss", xlabel="Epoch", ylabel="Binary cross-entropy")
    fig.tight_layout(); fig.savefig(plot_dir / "training_loss.png", dpi=160); plt.close(fig)
    fig, ax = plt.subplots(figsize=(7, 4)); scatter = ax.scatter(test_prob, test_unc, c=test_y, cmap="coolwarm", alpha=.6)
    ax.set(title="Bayesian prediction uncertainty", xlabel="Predicted SIC failure probability", ylabel="MC-dropout standard deviation"); fig.colorbar(scatter, ax=ax, label="Observed SIC failure")
    fig.tight_layout(); fig.savefig(plot_dir / "uncertainty_scatter.png", dpi=160); plt.close(fig)
    metrics = ["predicted_sic_failure_probability", "sic_failure_rate", "ber", "outage_probability", "throughput_mbps", "reliability"]
    labels = ["Pred. failure", "SIC failure", "BER", "Outage", "Throughput\n(Mbps)", "Reliability"]
    fig, axes = plt.subplots(2, 3, figsize=(11, 6));
    for ax, metric, label in zip(axes.flat, metrics, labels):
        comparison.plot(x="scheduler", y=metric, kind="bar", legend=False, color=["#999999", "#2ca25f"], ax=ax)
        ax.set(xlabel="", ylabel=label); ax.tick_params(axis="x", rotation=15)
    fig.suptitle("Conventional vs. reliability-aware NOMA scheduling", y=1.02, fontsize=14); fig.tight_layout()
    fig.savefig(plot_dir / "scheduling_comparison.png", dpi=180, bbox_inches="tight"); plt.close(fig)
